// One generation of the culture on the bench, run by the Bench screen's
// clock while `running`, and by Step. Reads the board and the rule, writes
// the next board, the generation, population, change and history (the last
// 120), and stops the run when the culture dies out or settles.
const ruleset = vars.get('ruleset');
const cells = vars.get('cells');
const gen = vars.get('gen');
let next;
if (ruleset === 'sand') next = await script.sandStep(cells, gen);
else if (ruleset === 'custom') next = await script.lifeStep(cells, vars.get('customBirth'), vars.get('customSurvive'));
else next = await script.lifeStep(cells, 8, 12);
let pop = 0, same = true;
for (let i = 0; i < next.length; i++) {
  const v = next[i];
  if (v !== 0 && v !== 3) pop++;
  if (same && v !== cells[i]) same = false;
}
const history = vars.get('history').concat([pop]);
if (history.length > 120) history.splice(0, history.length - 120);
const prev = history.length > 1 ? history[history.length - 2] : pop;
vars.set('cells', next);
vars.set('gen', gen + 1);
vars.set('pop', pop);
vars.set('delta', pop - prev);
vars.set('history', history);
if (vars.get('running')) {
  if (pop === 0 && ruleset !== 'sand') {
    vars.set('running', false); vars.set('noticeKind', 'extinct'); vars.set('noticeGen', gen + 1);
  } else if (same) {
    vars.set('running', false); vars.set('noticeKind', 'settled'); vars.set('noticeGen', gen);
  }
}
return { gen: gen + 1, pop };

// A slide's cells from their text: 2,304 characters, 0–9, a (10), b (11).
// Throws on anything else, so a damaged slide is an error.
if (typeof text !== 'string' || text.length !== 2304) throw new Error(`expected 2304 cells, got ${typeof text === 'string' ? text.length : 'none'}`);
const out = new Array(2304);
for (let i = 0; i < 2304; i++) {
  const c = text.charCodeAt(i);
  const v = c >= 48 && c <= 57 ? c - 48 : (c === 97 || c === 98 ? c - 87 : -1);
  if (v < 0) throw new Error(`bad cell “${text[i]}” at ${i}`);
  out[i] = v;
}
return out;

// One Life-like generation on a 48×48 torus. birth/survive are 9-bit masks
// (bit n = n live neighbours). Cells equal to 1 are live.
const N = 48;
const next = new Array(N * N);
for (let y = 0; y < N; y++) {
  const up = ((y + N - 1) % N) * N, row = y * N, down = ((y + 1) % N) * N;
  for (let x = 0; x < N; x++) {
    const l = (x + N - 1) % N, r = (x + 1) % N;
    const n = (cells[up + l] === 1) + (cells[up + x] === 1) + (cells[up + r] === 1) +
      (cells[row + l] === 1) + (cells[row + r] === 1) +
      (cells[down + l] === 1) + (cells[down + x] === 1) + (cells[down + r] === 1);
    const mask = cells[row + x] === 1 ? survive : birth;
    next[row + x] = (mask >> n) & 1;
  }
}
return next;

// Paints a stroke from cell (x0, y0) to (x1, y1) with a disc brush of
// `radius` (dx²+dy² ≤ r²+r) and `value`. max(|dx|,|dy|)+1 points, each
// rounded half up. Clips at the edges. Returns the new cells.
const N = 48;
const out = cells.slice();
const dx = x1 - x0, dy = y1 - y0;
const steps = Math.max(Math.abs(dx), Math.abs(dy));
const offs = [];
for (let oy = -radius; oy <= radius; oy++)
  for (let ox = -radius; ox <= radius; ox++)
    if (ox * ox + oy * oy <= radius * radius + radius) offs.push([ox, oy]);
for (let k = 0; k <= steps; k++) {
  const cx = steps === 0 ? x0 : Math.floor(x0 + dx * k / steps + 0.5);
  const cy = steps === 0 ? y0 : Math.floor(y0 + dy * k / steps + 0.5);
  for (const [ox, oy] of offs) {
    const x = cx + ox, y = cy + oy;
    if (x >= 0 && x < N && y >= 0 && y < N) out[y * N + x] = value;
  }
}
return out;

// Reads a Life-like rule: B3/S23, B3S23, S23/B3, B2/S, or the classic 23/3
// (survival/birth). Case and spaces ignored. Returns
// {ok: true, birth, survive, notation} (masks: bit n = count n) or
// {ok: false, error}.
const s = String(text ?? '').replace(/\s/g, '').toUpperCase();
if (s === '') return { ok: false, error: 'Enter a rule like B3/S23' };
const bad = s.match(/[^BS0-9/]/);
if (bad) return { ok: false, error: `“${bad[0]}” isn’t part of a rule. Use B<digits>/S<digits>` };
if (s.includes('9')) return { ok: false, error: 'Neighbour counts run 0–8 (found 9)' };
const mask = (d) => [...d].reduce((m, c) => m | (1 << Number(c)), 0);
const digits = (m) => [0, 1, 2, 3, 4, 5, 6, 7, 8].filter((d) => (m >> d) & 1).join('');
let b, sv, m;
if ((m = s.match(/^B([0-8]*)\/?S([0-8]*)$/))) { b = mask(m[1]); sv = mask(m[2]); }
else if ((m = s.match(/^S([0-8]*)\/?B([0-8]*)$/))) { b = mask(m[2]); sv = mask(m[1]); }
else if ((m = s.match(/^([0-8]*)\/([0-8]*)$/))) { b = mask(m[2]); sv = mask(m[1]); }
else return { ok: false, error: 'Use the form B<digits>/S<digits>, e.g. B36/S23' };
return { ok: true, birth: b, survive: sv, notation: `B${digits(b)}/S${digits(sv)}` };

// One falling-sand generation (SPEC.md "Falling sand"). 0 empty, 1 sand,
// 2 water, 3 wall, 4..11 fire with heat value-3. gen's parity picks the
// scan direction; (x + gen) % 2 picks the side tried first.
const N = 48;
const a = cells.slice();
const moved = new Uint8Array(N * N);
const even = gen % 2 === 0;
const inside = (x, y) => x >= 0 && x < N && y >= 0 && y < N;
function swap(i, t) {
  const v = a[i]; a[i] = a[t]; a[t] = v;
  moved[t] = 1;
  if (a[i] !== 0) moved[i] = 1;
}
for (let y = N - 1; y >= 0; y--) {
  for (let k = 0; k < N; k++) {
    const x = even ? k : N - 1 - k;
    const i = y * N + x;
    if (moved[i]) continue;
    const v = a[i];
    if (v === 0 || v === 3) continue;
    const dir = (x + gen) % 2 === 0 ? -1 : 1;
    if (v === 1) {
      for (const [dx, dy] of [[0, 1], [dir, 1], [-dir, 1]]) {
        const tx = x + dx, ty = y + dy;
        if (inside(tx, ty) && (a[ty * N + tx] === 0 || a[ty * N + tx] === 2)) { swap(i, ty * N + tx); break; }
      }
    } else if (v === 2) {
      for (const [dx, dy] of [[0, 1], [dir, 1], [-dir, 1], [dir, 0], [-dir, 0]]) {
        const tx = x + dx, ty = y + dy;
        if (inside(tx, ty) && a[ty * N + tx] === 0) { swap(i, ty * N + tx); break; }
      }
    } else if (v >= 4 && v <= 11) {
      let doused = false;
      for (const [dx, dy] of [[0, -1], [0, 1], [-1, 0], [1, 0]]) {
        const tx = x + dx, ty = y + dy;
        if (inside(tx, ty) && a[ty * N + tx] === 2) {
          a[ty * N + tx] = 0; moved[ty * N + tx] = 1;
          a[i] = 0; moved[i] = 1;
          doused = true;
          break;
        }
      }
      if (doused) continue;
      const heat = v - 4;
      if (heat <= 0) { a[i] = 0; continue; }
      const cooler = 3 + heat;
      let rose = false;
      for (const dx of [0, dir]) {
        const tx = x + dx, ty = y - 1;
        if (inside(tx, ty) && a[ty * N + tx] === 0) {
          a[ty * N + tx] = cooler; moved[ty * N + tx] = 1; a[i] = 0; rose = true;
          break;
        }
      }
      if (!rose) { a[i] = cooler; moved[i] = 1; }
    }
  }
}
return a;

// A random culture from `seed`: an LCG s ← (s·1664525 + 1013904223) mod 2³²,
// one draw (s / 2³²) per cell. Life/Custom: < 0.3 live. Sand: rows 0–23,
// < 0.22 sand, < 0.32 water.
const N = 48;
let s = seed >>> 0;
const out = new Array(N * N).fill(0);
for (let i = 0; i < N * N; i++) {
  s = (s * 1664525 + 1013904223) % 4294967296;
  const p = s / 4294967296;
  if (ruleset === 'sand') { if (i < 24 * N) out[i] = p < 0.22 ? 1 : (p < 0.32 ? 2 : 0); }
  else out[i] = p < 0.3 ? 1 : 0;
}
return out;

// Stamps a pattern (rows of 'O' live / '.' dead) centred on (cx, cy) after
// `rotation` quarter turns clockwise ((x, y) → (h−1−y, x)). Only live cells
// are written, as `value`. With `wrap` (Life, Custom) cells past an edge come
// in on the other side; otherwise they're dropped. Returns the new cells.
const N = 48;
let pts = [];
let w = rows[0].length, h = rows.length;
for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (rows[y][x] === 'O') pts.push([x, y]);
for (let r = 0; r < ((rotation % 4) + 4) % 4; r++) {
  pts = pts.map(([x, y]) => [h - 1 - y, x]);
  [w, h] = [h, w];
}
const out = cells.slice();
const ox = cx - Math.floor(w / 2), oy = cy - Math.floor(h / 2);
for (const [x, y] of pts) {
  let tx = ox + x, ty = oy + y;
  if (wrap) { tx = ((tx % N) + N) % N; ty = ((ty % N) + N) % N; }
  else if (tx < 0 || tx >= N || ty < 0 || ty >= N) continue;
  out[ty * N + tx] = value;
}
return out;
